<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Media;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;
class MediaController extends Controller { public function index(Request $r){return response()->json(Media::latest()->paginate(100));} public function store(Request $r){$d=$r->validate(['file'=>'required|file|mimes:jpg,jpeg,png,webp,avif,gif|max:10240','alt_text'=>'nullable|string|max:255','folder'=>'nullable|string|max:80']);$file=$r->file('file');$folder='media/'.preg_replace('/[^a-zA-Z0-9_-]/','',$d['folder']??'general');$path=$file->store($folder,'public');$m=Media::create(['filename'=>$file->getClientOriginalName(),'path'=>$path,'mime_type'=>$file->getMimeType(),'size'=>$file->getSize(),'alt_text'=>$d['alt_text']??null,'uploaded_by'=>$r->user()->id]);return response()->json(['data'=>$m,'url'=>Storage::disk('public')->url($path)],201);} public function update(Request $r,Media $medium){$d=$r->validate(['alt_text'=>'nullable|string|max:255']);$medium->update($d);return response()->json(['data'=>$medium]);} public function destroy(Media $medium){Storage::disk('public')->delete($medium->path);$medium->delete();return response()->json(['message'=>'Media deleted.']);} }
